    "Name": "AIAdmin",
    "Key": "AI",
    "ResourceKey": "AI",
    "Script": "AIAdmin = {
    init: async function (app, container) {
        container = container || $('.component[name=AIAdmin]');
        try {
            var response = await fetch('/Api/AI/Model/Providers', { credentials: 'same-origin' });
            if (!response.ok) throw new Error('HTTP ' + response.status);
            var result = await response.json();
            var providers = result.value || result.providers || result;
            if (!Array.isArray(providers)) providers = [];
            var list = $('[data-ai-providers]', container).empty();
            providers.forEach(function (provider) { $('<li>').text(provider.name || provider.Name || provider.key || provider.Key || String(provider)).appendTo(list); });
            if (!providers.length) list.append('<li>No provider inventory was returned; use model discovery to verify a known key.</li>');
        } catch (_) {
            $('[data-ai-providers]', container).html('<li>Provider inventory is not exposed by this deployment.</li>');
        }
    }
}",
    "Content": "<section class="ai-admin"><header><span>AI administration</span><h1>Providers and operations</h1><p>Validate the provider boundary without exposing credentials, then use deployment configuration to change secrets or defaults.</p></header><div class="ai-admin-grid"><section><h2>Configured providers</h2><ul data-ai-providers><li>Loading...</li></ul></section><section><h2>Configuration ownership</h2><dl><div><dt>Section</dt><dd><code>AI</code></dd></div><div><dt>Environment prefix</dt><dd><code>AI__</code></dd></div><div><dt>Secrets</dt><dd>Deployment environment only; never rendered here.</dd></div><div><dt>Domain disabled</dt><dd>Omit the complete AI configuration section.</dd></div></dl></section><section><h2>Operational checks</h2><ul><li>Provider endpoint responds.</li><li>Model catalogue is available.</li><li>Completion credentials are configured.</li><li>Agent iteration and timeout limits are bounded.</li></ul></section></div><p class="ai-admin-note">For interactive model discovery, open the <a href="/AI">AI workspace</a>.</p></section><style scoped>.ai-admin{padding:1.25rem;display:grid;gap:1.25rem}.ai-admin>header,.ai-admin-grid>section,.ai-admin-note{padding:1.25rem;border:var(--site-border);border-radius:var(--site-radius);background:white;box-shadow:var(--site-shadow)}.ai-admin>header span{text-transform:uppercase;letter-spacing:.1em;color:var(--site-secondary);font-weight:700}.ai-admin>header p,.ai-admin-note{padding:1.25rem}.ai-admin>header p:before,.ai-admin>header p:after,.ai-admin-note:before,.ai-admin-note:after{content:none}.ai-admin-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1rem}.ai-admin dl div{margin-bottom:.75rem}.ai-admin dt{color:var(--site-primary)}.ai-admin dd{margin-left:0}@media(max-width:800px){.ai-admin-grid{grid-template-columns:1fr}}</style>",
