    "Name": "AIWorkspace",
    "Key": "AI",
    "ResourceKey": "AI",
    "Script": "AIWorkspace = {
    init: function (app, container) {
        container = container || $('.component[name=AIWorkspace]');
        $('button[name=discoverModels]', container).on('click', async function () {
            var provider = $.trim($('input[name=provider]', container).val());
            var output = $('[data-ai-models]', container);
            if (!provider) { output.text('Enter a provider key first.'); return; }
            output.text('Discovering models...');
            try {
                var response = await fetch('/Api/AI/Model/Providers/' + encodeURIComponent(provider) + '/Available', { credentials: 'same-origin' });
                if (!response.ok) throw new Error('HTTP ' + response.status);
                var result = await response.json();
                var models = result.value || result.models || result;
                if (!Array.isArray(models)) models = [];
                output.empty();
                if (!models.length) { output.text('No models were returned.'); return; }
                models.forEach(function (model) { $('<li>').text(model.id || model.Id || model.name || model.Name || String(model)).appendTo(output); });
            } catch (error) {
                output.text('Model discovery failed: ' + error.message);
            }
        });
    }
}",
